const GENERAL_CONFIG = {};
function GS(key,cfg){
  GENERAL_CONFIG[key]=cfg;
  scenarios[key]={title:cfg.title,short:cfg.short||cfg.title,icon:cfg.icon||'◇',text:cfg.text,category:cfg.category};
  questionSets[key]=cfg.questions.map(q=>({key:q.key,kicker:q.kicker,title:q.title,help:q.help,options:q.options}));
  SCENARIO_GUIDE[key]={when:cfg.when,aim:cfg.aim,traps:cfg.traps,opening:cfg.opening};
  PSYCH_HINTS[key]={};cfg.questions.forEach(q=>PSYCH_HINTS[key][q.key]={listen:q.listen,ask:q.ask,caution:q.caution});
}
function GQ(key,kicker,title,help,options,listen,ask,caution){return{key,kicker,title,help,options,listen,ask,caution}}
function selected(s,key,a){return label(s,key,a[key]).toLowerCase()}

